def _collapse_widths(
    cls,
    widths: List[int],
    wrapable: List[bool],
    max_width: int,
    minimums: Optional[List[int]] = None,
) -> List[int]:
    """Reduce widths so that the total is under max_width.

    Args:
        widths (List[int]): List of widths.
        wrapable (List[bool]): List of booleans that indicate if a column may shrink.
        max_width (int): Maximum width to reduce to.
        minimums (List[int], optional): Minimum width for each column. Columns
            are never shrunk below their minimum. Defaults to None (no minimums).

    Returns:
        List[int]: A new list of widths.
    """
    if minimums is None:
        minimums = [0] * len(widths)
    total_width = sum(widths)
    excess_width = total_width - max_width
    if any(wrapable):
        while total_width and excess_width > 0:
            # Only columns that may shrink and are still above their minimum
            shrinkable = [
                allow_wrap and width > minimum
                for width, allow_wrap, minimum in zip(widths, wrapable, minimums)
            ]
            if not any(shrinkable):
                break
            max_column = max(
                width for width, allow_wrap in zip(widths, shrinkable) if allow_wrap
            )
            second_max_column = max(
                width if allow_wrap and width != max_column else 0
                for width, allow_wrap in zip(widths, shrinkable)
            )
            column_difference = max_column - second_max_column
            ratios = [
                (1 if (width == max_column and allow_wrap) else 0)
                for width, allow_wrap in zip(widths, shrinkable)
            ]
            if not any(ratios) or not column_difference:
                break
            max_reduce = [
                min(excess_width, column_difference, width - minimum)
                for width, minimum in zip(widths, minimums)
            ]
            widths = ratio_reduce(excess_width, ratios, max_reduce, widths)

